class Solution {
    fun solution(dots: Array<IntArray>): Int {

        val x1 = dots[0][0]
        val y1 = dots[0][1]
        val x2 = dots[1][0]
        val y2 = dots[1][1]
        val x3 = dots[2][0]
        val y3 = dots[2][1]
        val x4 = dots[3][0]
        val y4 = dots[3][1]

        var a = (y1-y2)*(x3-x4)
        var b = (x1-x2)*(y3-y4)

        if(a==b) return 1

        var c = (y1-y3)*(x2-x4)
        var d = (x1-x3)*(y2-y4)

        if(c==d) return 1

        var e = (y1-y4)*(x2-x3)
        var f = (x1-x4)*(y2-y3)

        if(e==f) return 1

        return 0
    }
}

class Solution {
    fun solution(n: Int): Array<IntArray> {
        val answer = Array(n) { IntArray(n) }
        var num = 1
        var top = 0
        var bottom = n - 1
        var left = 0
        var right = n - 1
        while(num < ( n*n + 1 )){
            for (i in left..right){
                answer[top][i] = num++
            }
            top++
            for (i in top..bottom){
                answer[i][right] = num++
            }
            right--
            for (i in right downTo left){
                answer[bottom][i] = num++
            }
            bottom--
            for (i in bottom downTo top){
                answer[i][left] = num++
            }
            left++
        }


        return answer
    }
}

