class Solution {
    fun solution(a: Int, b: Int, c: Int, d: Int): Int {
        var answer: Int = 0

        if (a == b && b == c && c == d && a == d) answer = 1111 * a

        else if (a == b && b == c && a != d) answer = ( 10 * a + d ) * ( 10 * a + d )
        else if (a == c && c == d && a != b) answer = ( 10 * a + b ) * ( 10 * a + b )
        else if (b == c && c == d && b != a) answer = ( 10 * b + a ) * ( 10 * b + a )
        else if (a == b && b == d && a != c) answer = ( 10 * a + c ) * ( 10 * a + c )

        else if (a == b && c == d && a != c) answer = (a + c) * abs(a - c)
        else if (a == c && b == d && a != b) answer = (a + b) * abs(a - b)
        else if (a == d && b == c && a != b) answer = (a + b) * abs(a - b)

        else if (a == b) answer = c * d
        else if (a == c) answer = b * d
        else if (a == d) answer = b * c
        else if (b == c) answer = a * d
        else if (b == d) answer = a * c
        else if (c == d) answer = a * b

        else answer = minOf(a, b, c, d)

        return answer
    }
}

class Solution {
    fun solution(numer1: Int, denom1: Int, numer2: Int, denom2: Int): IntArray {
        var answer: IntArray = intArrayOf()
        var commonNumer = (numer1 * denom2) + (numer2 * denom1)
        var commonDenom = denom1 * denom2

        fun getGCD(a: Int, b: Int): Int {
            return if (b == 0) a else getGCD(b, a % b)
        }

        val gcd = getGCD(commonNumer, commonDenom)

        answer = intArrayOf(commonNumer / gcd, commonDenom / gcd)
        return answer
    }
}
